function login() {
     java.startBrowserAwait("https://66shuba.com/login", '66书吧');
}

function xflogin() {
java.startBrowserAwait(ho, '起点');
}

function dp() {
	let dpkg = String(source.getVariable())
	if (dpkg == '0') {
		source.setVariable('1');
		java.longToast("\n\n段评已开启");
		} else {
			source.setVariable('0');
		java.longToast("\n\n段评已关闭");
			}
	}

